<?php
declare(strict_types=1);
require_once __DIR__ . '/includes/auth.php'; require_once __DIR__ . '/includes/db.php'; $adminUser=requireAdmin(); $adminPageTitle='Availability & Schedules';
$schedules=$adminConnection->query('SELECT s.*, c.name AS center_name FROM center_schedules s JOIN dialysis_centers c ON c.id=s.center_id ORDER BY s.schedule_date, s.schedule_time LIMIT 200')->fetchAll(); $centers=$adminConnection->query("SELECT id,name FROM dialysis_centers WHERE status='Active' ORDER BY name")->fetchAll(); require __DIR__ . '/includes/header.php';
?><div class="admin-panel"><div class="admin-panel-heading"><h2>Add availability schedule</h2></div><form method="post" action="actions/save_schedule.php" class="admin-form-grid"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars(getCsrfToken(),ENT_QUOTES,'UTF-8') ?>"><label class="admin-field">Center<select name="center_id" required><?php foreach($centers as $center): ?><option value="<?= (int)$center['id'] ?>"><?= htmlspecialchars($center['name'],ENT_QUOTES,'UTF-8') ?></option><?php endforeach; ?></select></label><label class="admin-field">Date<input type="date" name="schedule_date" min="<?= date('Y-m-d') ?>" required></label><label class="admin-field">Time<input type="time" name="schedule_time" required></label><label class="admin-field">Dialysis type<select name="dialysis_type"><option>Hemodialysis</option><option>Peritoneal Dialysis</option><option>Home Hemodialysis</option><option>Continuous Ambulatory Peritoneal Dialysis</option><option>Automated Peritoneal Dialysis</option></select></label><label class="admin-field">Available slots<input type="number" name="available_slots" min="0" required></label><button class="admin-btn" type="submit">Add Schedule</button></form></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Date</th><th>Time</th><th>Center</th><th>Dialysis type</th><th>Available</th><th>Reserved</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($schedules as $row): ?><tr><td><?= htmlspecialchars($row['schedule_date'],ENT_QUOTES,'UTF-8') ?></td><td><?= htmlspecialchars(substr($row['schedule_time'],0,5),ENT_QUOTES,'UTF-8') ?></td><td><?= htmlspecialchars($row['center_name'],ENT_QUOTES,'UTF-8') ?></td><td><?= htmlspecialchars($row['dialysis_type'],ENT_QUOTES,'UTF-8') ?></td><td><?= (int)$row['available_slots'] ?></td><td><?= (int)$row['reserved_slots'] ?></td><td><span class="admin-status"><?= htmlspecialchars($row['status'],ENT_QUOTES,'UTF-8') ?></span></td><td><form method="post" action="actions/delete_schedule.php"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars(getCsrfToken(),ENT_QUOTES,'UTF-8') ?>"><input type="hidden" name="schedule_id" value="<?= (int)$row['id'] ?>"><button class="admin-btn admin-btn-danger" type="submit">Remove</button></form></td></tr><?php endforeach; ?></tbody></table><?php if(!$schedules): ?><p class="admin-empty">No schedules created yet.</p><?php endif; ?></div><?php require __DIR__ . '/includes/footer.php'; ?>
